#!/bin/sh
# Fetch the images of docker-compose.yaml by digest into images/ (generated by hydo compose; hydo-build
# never pulls). Needs hydo-fetch-image (it comes with hydo) and network access, once.
# It fetches the images this machine builds: x86_64 on Linux, arm64 on a Mac. Name
# x86_64, arm64 or all as the argument to choose (sh fetch-images.sh all).
# The Compose file's S3 server (rclone) is left out: under hydo it is the S3 emulator, whose
# image hydo build fetches into emulators/.
set -eu
cd "$(dirname "$0")"
A=${1:-}
[ -n "$A" ] || case "$(uname -s)" in Darwin) A=arm64;; *) A=x86_64;; esac
case "$A" in x86_64|arm64|all) ;; *) echo "fetch-images.sh: x86_64, arm64 or all (got $A)" >&2; exit 2;; esac
F=${HYDO_FETCH_IMAGE:-$(command -v hydo-fetch-image || true)}
[ -n "$F" ] || { echo "fetch-images.sh: hydo-fetch-image not found (put hydo's bin directory on PATH, or set HYDO_FETCH_IMAGE)" >&2; exit 1; }
mkdir -p images
[ "$A" = x86_64 ] || [ -e images/quay.io-coreos-etcd-v3.6.17-arm64-oci ] || "$F" quay.io/coreos/etcd sha256:960ea8d19062c3e2e85cb827884fa002fffa754616071f86f01196a1fdd42bc8 quay.io/coreos/etcd:v3.6.17 images/quay.io-coreos-etcd-v3.6.17-arm64-oci
[ "$A" = arm64 ] || [ -f images/quay.io-coreos-etcd-v3.6.17-amd64.docker.tar ] || "$F" quay.io/coreos/etcd sha256:c521f860433f4f1696e95ff2124c90e8a979766c8443f5f487bdf1b02d238de2 quay.io/coreos/etcd:v3.6.17 images/quay.io-coreos-etcd-v3.6.17-amd64.docker.tar
[ "$A" = x86_64 ] || [ -e images/apache-kafka-3.9.1-arm64-oci ] || "$F" docker.io/apache/kafka sha256:39bc3b30084ad6ab33ad2c9a525f15c942bf097b18cb2a1825afa6df3411f8b5 apache/kafka:3.9.1 images/apache-kafka-3.9.1-arm64-oci
[ "$A" = arm64 ] || [ -f images/apache-kafka-3.9.1-amd64.docker.tar ] || "$F" docker.io/apache/kafka sha256:5862db4a63a6dd7d46fd14771b10a1b39e069c2c47f17d8e4640f960720a0ead apache/kafka:3.9.1 images/apache-kafka-3.9.1-amd64.docker.tar
[ "$A" = x86_64 ] || [ -e images/greptime-greptimedb-v1.3.1-arm64-oci ] || "$F" docker.io/greptime/greptimedb sha256:c026fa2b8db730ff392c67b46ca723ee50604e01592b16b3847c39941c824366 greptime/greptimedb:v1.3.1 images/greptime-greptimedb-v1.3.1-arm64-oci
[ "$A" = arm64 ] || [ -f images/greptime-greptimedb-v1.3.1-amd64.docker.tar ] || "$F" docker.io/greptime/greptimedb sha256:f539f3780cf7331e5203c4687f2f88f2d570718300cb8990d9d7490e9db114a5 greptime/greptimedb:v1.3.1 images/greptime-greptimedb-v1.3.1-amd64.docker.tar
